        / Utility classes /
        .hidden {
            display: none !important;
        }

        .sronly {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: 1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            whitespace: nowrap;
            border: 0;
        }

        / Additional polish for 2025 stateoftheart feel /
        @media (prefersreducedmotion: reduce) {
            ,
            ::before,
            ::after {
                animationduration: 0.01ms !important;
                animationiterationcount: 1 !important;
                transitionduration: 0.01ms !important;
            }
        }

        / Enhanced text selection /
        ::selection {
            background: var(accentglow);
            color: var(white);
