    </style>
</head>
<body>
    <! Header >
    <header class="header">
        <div class="headercontent">
            <a href="" class="logo" lang="hu">Aura</a>
            <div class="headeractions">
                <button class="iconbtn" arialabel="Beállítások">
                    <i class="materialicons">tune</i>
                </button>
                <button class="iconbtn" arialabel="Felhasználói menü">
                    <i class="materialicons">person_outline</i>
                </button>
            </div>
        </div>
    </header>

    <! Main Content >
    <main class="main">
        <! Search Hero >
        <section class="searchhero">
            <h1 class="searchtitle" lang="hu">Keresés</h1>
            <p class="searchsubtitle" lang="hu">Keress bármire!</p>

            <div class="searchcontainer">
                <div class="searchbox">
                    <i class="materialicons searchicon">search</i>
                    <input 
                        type="text" 
                        class="searchinput" 
                        placeholder="Mit keresel ma?"
                        id="searchInput"
                        autocomplete="off"
                        lang="hu"
                    >
                    <button class="searchbtn" id="searchBtn" arialabel="Keresés">
                        <i class="materialicons">arrow_forward</i>
                    </button>
                </div>

                <! Search Suggestions >
                <div class="suggestions" id="suggestions">
                    <div class="suggestion">
                        <i class="materialicons suggestionicon">trending_up</i>
                        <span>Gépi tanulás trendek</span>
                    </div>
                    <div class="suggestion">
                        <i class="materialicons suggestionicon">palette</i>
                        <span>Dizájn inspiráció</span>
                    </div>
                    <div class="suggestion">
                        <i class="materialicons suggestionicon">code</i>
                        <span>Webfejlesztés</span>
                    </div>
                    <div class="suggestion">
                        <i class="materialicons suggestionicon">psychology</i>
                        <span>Tudatosság gyakorlatok</span>
                    </div>
                </div>
            </div>
        </section>

        <! Results Section >
        <section class="resultssection hidden" id="resultsSection">
            <div class="resultsheader">
                <div class="resultsinfo">
                    Körülbelül <span id="resultsCount">847 000</span> eredmény (0,14 másodperc)
                </div>
                <div class="viewtoggle">
                    <button class="togglebtn active" dataview="grid">
                        <i class="materialicons">grid_view</i>
                        Rács
                    </button>
                    <button class="togglebtn" dataview="list">
                        <i class="materialicons">view_list</i>
                        Lista
                    </button>
                </div>
            </div>

            <div class="resultsgrid" id="resultsGrid">
                <! Results will be populated here >
            </div>

            <! Pagination >
            <nav class="pagination">
                <button class="pagebtn" arialabel="Előző oldal">
                    <i class="materialicons">chevron_left</i>
                </button>
                <button class="pagebtn active">1</button>
                <button class="pagebtn">2</button>
                <button class="pagebtn">3</button>
                <button class="pagebtn">4</button>
                <button class="pagebtn">5</button>
                <button class="pagebtn" arialabel="Következő oldal">
                    <i class="materialicons">chevron_right</i>
                </button>
            </nav>
        </section>
    </main>

    <script>
        // Enhanced, elegant JavaScript for premium interactions
        class AuraSearchHU {
            constructor() {
                this.searchInput = document.getElementById('searchInput');
                this.searchBtn = document.getElementById('searchBtn');
                this.suggestions = document.getElementById('suggestions');
                this.resultsSection = document.getElementById('resultsSection');
                this.resultsGrid = document.getElementById('resultsGrid');
                this.searchTimeout = null;
                this.isTabbing = false;

                this.init();
            }

            init() {
                this.bindEvents();
                this.generateSampleResults();
                this.setupAccessibility();
                this.initializeAnimations();
            }

            bindEvents() {
                // Search input events with enhanced UX
                this.searchInput.addEventListener('input', this.handleInput.bind(this));
                this.searchInput.addEventListener('focus', this.showSuggestions.bind(this));
                this.searchInput.addEventListener('blur', this.hideSuggestionsDelayed.bind(this));
                this.searchInput.addEventListener('keydown', this.handleKeyDown.bind(this));

                // Enhanced search button with microinteractions
                this.searchBtn.addEventListener('click', this.handleSearch.bind(this));
                this.searchBtn.addEventListener('mousedown', this.addRippleEffect.bind(this));

                // Suggestions with improved interaction
                this.suggestions.addEventListener('mousedown', this.handleSuggestionClick.bind(this));

                // View toggle with smooth transitions
                document.querySelectorAll('.togglebtn').forEach(btn => {
                    btn.addEventListener('click', this.handleViewToggle.bind(this));
                });

                // Enhanced outside click handling
                document.addEventListener('click', this.handleOutsideClick.bind(this));

                // Smooth scroll handling
                window.addEventListener('scroll', this.handleScroll.bind(this));

                // Tab navigation tracking for accessibility
