            color: white;
            bordercolor: var(accent);
            transform: translateY(2px);
            boxshadow: 0 8px 24px rgba(237, 1, 127, 0.3);
        }

        / Enhanced Animations /
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(40px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes gradientShift {
            0%, 100% { 
                backgroundposition: 0% 50%; 
